const parseBody = (value) => {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
};
const fit = (value, limit = 1024) => {
  const safe = String(value ?? '').replaceAll('@', '@\u200b').trim();
  if (!safe) return 'None.';
  return safe.length <= limit ? safe : safe.slice(0, limit - 2).trimEnd() + '…';
};
const socResponse = $('Read preflight SOC snapshot').first().json;
const soc = parseBody(socResponse.body ?? socResponse) ?? {};
const metadata = $('Select preflight evaluation').first().json;
const response = items[0]?.json ?? {};
const body = parseBody(response.body ?? response);
const builds = Array.isArray(body) ? body : [];
const expected = [
  'anvil', 'atlas', 'casebook', 'courier', 'forge', 'herald', 'hound',
  'identity', 'loom', 'lure', 'mac', 'mitm', 'nixos', 'oracle', 'pixie',
  'scout', 'sieve', 'soc', 'websites',
].map((name) => `production.${name}`);
const byJob = new Map(builds.map((build) => [build.job, build]));
const states = expected.map((job) => {
  const build = byJob.get(job);
  if (!build || Number(build.finished) !== 1) return { job, state: 'pending' };
  if (Number(build.buildstatus) !== 0 || !Object.values(build.buildoutputs ?? {}).some((output) => output?.path)) return { job, state: 'failed' };
  return { job, state: 'succeeded' };
});
const failedJobs = states.filter((item) => item.state === 'failed');
const pendingJobs = states.filter((item) => item.state === 'pending');
const fleet = soc.fleet ?? {};
const services = soc.services ?? {};
const maintenance = soc.maintenance ?? {};
const deployment = soc.deployment ?? {};
const security = soc.security ?? {};
const blockers = [];
const warnings = [];
if (!metadata.available || builds.length === 0) blockers.push('Hydra production evaluation is unavailable');
if (failedJobs.length) blockers.push(`Hydra failed: ${failedJobs.map((item) => item.job.replace('production.', '')).join(', ')}`);
if (pendingJobs.length) blockers.push(`Hydra incomplete: ${pendingJobs.length} production job(s) pending`);
if ((fleet.down_hosts ?? []).length) blockers.push(`Hosts down: ${fleet.down_hosts.join(', ')}`);
if ((fleet.failed_units ?? []).length) blockers.push(`Failed units: ${fleet.failed_units.slice(0, 6).map((item) => `${item.host}/${item.unit}`).join(', ')}`);
if ((services.unavailable ?? []).length) blockers.push(`${services.unavailable.length} monitored endpoint(s) unavailable`);
if ((maintenance.stale_backups ?? []).length) blockers.push(`Stale backups: ${maintenance.stale_backups.map((item) => `${item.host}/${item.timer}`).join(', ')}`);
const deployFailures = [...(deployment.deployment_failures ?? []), ...(deployment.build_failures ?? []), ...(deployment.fetch_failures ?? [])];
if (deployFailures.length) blockers.push(`comin failures: ${[...new Set(deployFailures)].join(', ')}`);
if ((deployment.drifted_hosts ?? []).length) blockers.push(`Deployment drift: ${deployment.drifted_hosts.join(', ')}`);
const criticalDisks = (fleet.disk_attention ?? []).filter((item) => Number(item.used_percent) >= 90);
if (criticalDisks.length) blockers.push(`Root disk ≥90%: ${criticalDisks.map((item) => `${item.host} ${Number(item.used_percent).toFixed(1)}%`).join(', ')}`);
if ((services.internal_acme_attention ?? []).length) blockers.push('Internal ACME renewal is inside the four-hour critical window');
if (Number(security.opencanary_interactions ?? 0) > 0) blockers.push('OpenCanary activity exists in the last 24 hours');
const warningDisks = (fleet.disk_attention ?? []).filter((item) => Number(item.used_percent) >= 80 && Number(item.used_percent) < 90);
if (warningDisks.length) warnings.push(`Disk pressure: ${warningDisks.map((item) => `${item.host} ${Number(item.used_percent).toFixed(1)}%`).join(', ')}`);
if ((deployment.reboot_pending ?? []).length) warnings.push(`Reboot pending: ${deployment.reboot_pending.join(', ')}`);
if ((services.slow ?? []).length) warnings.push(`${services.slow.length} endpoint(s) slower than two seconds`);
if ((services.external_tls_attention ?? []).length) warnings.push(`${services.external_tls_attention.length} non-ACME certificate(s) expire within 30 days`);
if (Number(security.suricata_alerts ?? 0) + Number(security.pfsense_high_alerts ?? 0) > 0) warnings.push('Review recent IDS activity before changing the fleet');
if (Object.keys(soc.errors ?? {}).length) blockers.push('SOC operator snapshot is incomplete');
const decision = blockers.length ? 'NO-GO' : warnings.length ? 'GO WITH CAUTION' : 'GO';
const color = decision === 'GO' ? 0xa6e3a1 : decision === 'GO WITH CAUTION' ? 0xf9e2af : 0xf38ba8;
const blockerText = blockers.length ? blockers.map((item) => `⛔ ${item}`).join('\n') : '✅ No blocking condition found.';
const warningText = warnings.length ? warnings.map((item) => `⚠️ ${item}`).join('\n') : '✅ No caution condition found.';
const hydraText = [
  `Revision: **${metadata.revision || 'unknown'}**`,
  `Production jobs: **${states.filter((item) => item.state === 'succeeded').length}/${expected.length} succeeded**`,
  `Failed: **${failedJobs.length}** · Pending: **${pendingJobs.length}**`,
  `[Open evaluation](${metadata.evaluationUrl})`,
].join('\n');
const liveText = [
  `Comin revision: **${String(deployment.majority_commit ?? 'unknown').slice(0, 8)}** on ${Number(deployment.targets ?? 0)} host(s)`,
  `Node exporters: **${Number(fleet.node_targets ?? 0) - (fleet.down_hosts ?? []).length}/${Number(fleet.node_targets ?? 0)} up**`,
  `Service probes: **${Number(services.checked ?? 0) - (services.unavailable ?? []).length}/${Number(services.checked ?? 0)} up**`,
  `Backups: **${(maintenance.backups ?? []).length - (maintenance.stale_backups ?? []).length}/${(maintenance.backups ?? []).length} fresh**`,
].join('\n');
const discordEmbed = {
  author: { name: 'GUILDEDTHORN // CHANGE WINDOW' },
  title: `${decision} · ThornixOS fleet preflight`,
  description: decision === 'GO' ? 'The deployment pipeline and live fleet satisfy every preflight condition.' : 'Resolve or explicitly accept the conditions below before starting the rollout.',
  color,
  fields: [
    { name: '🚦 Blockers', value: fit(blockerText), inline: false },
    { name: '⚠️ Cautions', value: fit(warningText), inline: false },
    { name: '🏗️ Hydra candidate', value: fit(hydraText), inline: false },
    { name: '🖥️ Live fleet', value: fit(liveText), inline: false },
  ],
  footer: { text: 'Manual evidence-based preflight · observation only' },
  timestamp: new Date().toISOString(),
};
return [{ json: { discordEmbed, decision, blockers, warnings } }];
